@DisplayName("R4 멱등성")
class IdempotencyApiTest extends IntegrationTest {

    @Test
    @DisplayName("R4.2 같은 키·같은 요청은 다시 처리하지 않고 최초 응답(상태·본문)을 돌려준다")
